import {render,screen} from "@testing-library/react";import {expect,test,vi} from "vitest";import type {Metric} from "web-vitals";import {createCollector} from "./collector";import {startVitals,beaconSender,type Registration} from "./monitoring";import {p75,rate,safeMetric,type RecordMetric} from "./vitalModel";import {VitalsPage} from "./VitalsPage";
const metric=(id:string,value:number,name:Metric["name"]="LCP")=>({id,value,name});
test("kolektor zachowuje najnowszą wartość i nie sumuje duplikatów",()=>{const send=vi.fn(()=>true),collector=createCollector(send,"tickets");collector.accept(metric("a",2400));collector.accept(metric("a",2600));expect(collector.pendingCount()).toBe(1);collector.flush();expect(send).toHaveBeenCalledExactlyOnceWith([{id:"a",name:"LCP",value:2600,rating:"needs-improvement",route:"tickets"}]);collector.accept(metric("a",2600));collector.flush();expect(send).toHaveBeenCalledTimes(1);collector.accept(metric("a",2700));collector.flush();expect(send).toHaveBeenCalledTimes(2);});
test("nieudane kolejkowanie nie usuwa oczekujących danych",()=>{const send=vi.fn().mockReturnValueOnce(false).mockReturnValue(true),collector=createCollector(send,"home");collector.accept(metric("a",100));expect(collector.flush()).toBe(false);expect(collector.pendingCount()).toBe(1);expect(collector.flush()).toBe(true);expect(collector.pendingCount()).toBe(0);});
test("kolektor zachowuje zmianę otrzymaną w trakcie flush",()=>{let collector:ReturnType<typeof createCollector>;collector=createCollector(()=>{collector.accept(metric("a",3000));return true;},"home");collector.accept(metric("a",2000));collector.flush();expect(collector.pendingCount()).toBe(1);});
test("dane DOM i identyfikatory trasy nie są kopiowane do rekordu",()=>{const input={id:"a",name:"LCP",value:100,entries:[{element:"secret-selector"}],path:"/tickets/123?token=secret"};expect(JSON.stringify(safeMetric(input,"tickets"))).not.toContain("secret");expect(Object.keys(safeMetric(input,"tickets")!)).toEqual(["id","name","value","rating","route"]);});
test("limit oczekujących pomiarów oraz odrzucenie niepoprawnych wartości",()=>{const collector=createCollector(()=>true,"home");for(let i=0;i<30;i++)collector.accept(metric(String(i),i));expect(collector.pendingCount()).toBe(20);collector.accept(metric("bad",NaN));expect(collector.pendingCount()).toBe(20);expect(safeMetric({id:"",name:"LCP",value:1},"home")).toBeNull();});
test("hidden oraz pagehide nie powielają tej samej próbki, a stop usuwa własne listenery",()=>{const doc=new EventTarget() as EventTarget&{visibilityState:string};doc.visibilityState="visible";const page=new EventTarget();let report!:(metric:Metric)=>void;const register:Registration=callback=>{report=callback;};const send=vi.fn(()=>true),monitor=startVitals({send,route:"home",doc:doc as unknown as Document,page:page as unknown as Window,register});report({...metric("a",200),rating:"good",delta:200,entries:[],navigationType:"navigate"} as Metric);doc.visibilityState="hidden";doc.dispatchEvent(new Event("visibilitychange"));page.dispatchEvent(new Event("pagehide"));expect(send).toHaveBeenCalledTimes(1);monitor.stop();report({...metric("b",300),rating:"good",delta:300,entries:[],navigationType:"navigate"} as Metric);page.dispatchEvent(new Event("pagehide"));expect(send).toHaveBeenCalledTimes(1);});
test("beacon false uruchamia pojedynczy fallback keepalive",()=>{const beacon=vi.fn(()=>false),fetcher=vi.fn().mockResolvedValue(new Response(null,{status:204}));const records:RecordMetric[]=[{id:"a",name:"LCP",value:2000,rating:"good",route:"home"}];expect(beaconSender(beacon,fetcher)(records)).toBe(true);expect(beacon).toHaveBeenCalledTimes(1);expect(fetcher).toHaveBeenCalledExactlyOnceWith("/api/vitals",expect.objectContaining({method:"POST",keepalive:true,body:JSON.stringify(records)}));});
test("zaakceptowany beacon nie uruchamia fetch",()=>{const fetcher=vi.fn();expect(beaconSender(()=>true,fetcher)([])).toBe(true);expect(fetcher).not.toHaveBeenCalled();});
test("hero ma zarezerwowane proporcje oraz priorytet, a dalszy obraz jest lazy",()=>{render(<VitalsPage flush={()=>{}}/>);const hero=screen.getByRole("img",{name:"Panel aktywności DevDesk"});expect(hero).toHaveAttribute("width","1200");expect(hero).toHaveAttribute("height","480");expect(hero).toHaveAttribute("loading","eager");expect(hero).toHaveAttribute("fetchpriority","high");expect(hero).toHaveAttribute("srcset");expect(screen.getByRole("img",{name:"Miniatura panelu"})).toHaveAttribute("loading","lazy");});
test("nearest-rank p75 nie mutuje źródła i brak danych nie jest zerem",()=>{const source=[4000,1000,3000,2000];expect(p75(source)).toBe(3000);expect(source).toEqual([4000,1000,3000,2000]);expect(p75([])).toBeNull();expect(rate("INP",200)).toBe("good");});
